import ij.*;import ij.process.*;import ij.macro.Interpreter;import services.multiplex.util.IJUtils;
public class ReviewMultiplexBatchSelection {public static void main(String[] args){Interpreter.batchMode=true;ImagePlus a=new ImagePlus("review_ref",new ByteProcessor(8,8)),b=new ImagePlus("review_target",new ByteProcessor(8,8));a.show();b.show();System.out.println("ref_window="+a.getWindow()+" target_window="+b.getWindow()+" before="+WindowManager.getCurrentImage().getTitle());IJUtils.selectWindow(a.getTitle());System.out.println("after_helper="+WindowManager.getCurrentImage().getTitle());if(WindowManager.getCurrentImage()==a)throw new AssertionError("Expected reproduced selection failure");IJ.selectWindow(a.getTitle());System.out.println("after_IJ_selectWindow="+WindowManager.getCurrentImage().getTitle());if(WindowManager.getCurrentImage()!=a)throw new AssertionError("Control failed");a.close();b.close();Interpreter.batchMode=false;}}
